176→// classifySession determines if a session is stuck and returns diagnostic info.
177→// Returns nil if the session is healthy.
178→func classifySession(state *strategy.SessionState, repo *git.Repository, now time.Time) *stuckSession {
179→	// Determine shadow branch info
180→	shadowBranch := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
181→	refName := plumbing.NewBranchReferenceName(shadowBranch)
182→	_, refErr := repo.Reference(refName, true)
183→	hasShadowBranch := refErr == nil
184→
185→	switch {
186→	case state.Phase.IsActive():
187→		// Active sessions are stuck if no interaction for over the staleness threshold
188→		isStale := state.LastInteractionTime == nil || now.Sub(*state.LastInteractionTime) > stalenessThreshold
189→		if !isStale {
190→			return nil
191→		}
192→
193→		var reason string
194→		if state.LastInteractionTime != nil {
195→			reason = fmt.Sprintf("active, last interaction %s ago", now.Sub(*state.LastInteractionTime).Truncate(time.Minute))
196→		} else {
197→			reason = "active, no recorded interaction time"
198→		}
199→
200→		return &stuckSession{
201→			State:             state,
202→			Reason:            reason,
203→			ShadowBranch:      shadowBranch,
204→			HasShadowBranch:   hasShadowBranch,
205→			CheckpointCount:   state.StepCount,
206→			FilesTouchedCount: len(state.FilesTouched),
207→		}
208→
209→	case state.Phase == session.PhaseEnded:
210→		// Ended sessions are stuck if they have uncondensed data
211→		if state.StepCount <= 0 || !hasShadowBranch {
212→			return nil
213→		}
214→
215→		return &stuckSession{
216→			State:             state,
217→			Reason:            "ended with uncondensed checkpoint data",
218→			ShadowBranch:      shadowBranch,
219→			HasShadowBranch:   hasShadowBranch,
220→			CheckpointCount:   state.StepCount,
221→			FilesTouchedCount: len(state.FilesTouched),
222→		}
223→
224→	default:
225→		return nil
226→	}
227→}
