361→// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
362→// Returns true if no other sessions (besides excludeSessionID) need this branch.
363→func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
364→	states, err := strategy.ListSessionStates(ctx)
365→	if err != nil {
366→		return false, fmt.Errorf("failed to list session states: %w", err)
367→	}
368→
369→	for _, state := range states {
370→		if state.SessionID == excludeSessionID {
371→			continue
372→		}
373→		otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
374→		if otherShadow == shadowBranch && state.StepCount > 0 {
375→			return false, nil
376→		}
377→	}
378→
379→	return true, nil
380→}
