352→// resolveWorktreeBranch resolves the current branch for a worktree path
353→// by reading the HEAD ref directly from the filesystem
354→func resolveWorktreeBranch(ctx context.Context, worktreePath string) string {
355→	gitPath := filepath.Join(worktreePath, ".git")
356→
357→	fi, err := os.Stat(gitPath)
358→	if err != nil {
359→		return ""
360→	}
361→
362→	var headPath string
363→	if fi.IsDir() {
364→		// Regular repo: .git is a directory
365→		headPath = filepath.Join(gitPath, "HEAD")
366→	} else {
367→		// Worktree: .git is a file containing "gitdir: <path>"
368→		data, err := os.ReadFile(gitPath) //nolint:gosec // path derived from known worktree dir
369→		if err != nil {
370→			return ""
371→		}
372→		content := strings.TrimSpace(string(data))
373→		if !strings.HasPrefix(content, "gitdir: ") {
374→			return ""
375→		}
376→		gitdirPath := strings.TrimPrefix(content, "gitdir: ")
377→		if !filepath.IsAbs(gitdirPath) {
378→			gitdirPath = filepath.Join(worktreePath, gitdirPath)
379→		}
380→		headPath = filepath.Join(gitdirPath, "HEAD")
381→	}
382→
383→	data, err := os.ReadFile(headPath) //nolint:gosec // path constructed from .git/HEAD
384→	if err != nil {
385→		return ""
386→	}
387→
388→	ref := strings.TrimSpace(string(data))
389→
390→	// Symbolic ref: "ref: refs/heads/<branch>"
391→	if strings.HasPrefix(ref, "ref: refs/heads/") {
392→		branch := strings.TrimPrefix(ref, "ref: refs/heads/")
393→		// Reftable ref storage uses "ref: refs/heads/.invalid" as a dummy HEAD stub.
394→		// Fall back to git to resolve the actual branch in that case.
395→		if branch == ".invalid" {
396→			return resolveWorktreeBranchGit(ctx, worktreePath)
397→		}
398→		return branch
399→	}
400→
401→	// Detached HEAD or other ref type
402→	return detachedHEADDisplay
403→}
404→
405→// resolveWorktreeBranchGit resolves the branch name by shelling out to git.
406→// Used as a fallback for reftable ref storage where .git/HEAD is a stub.
407→func resolveWorktreeBranchGit(ctx context.Context, worktreePath string) string {
408→	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
409→	defer cancel()
410→	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--symbolic-full-name", "HEAD")
411→	out, err := cmd.Output()
412→	if err != nil {
413→		return detachedHEADDisplay
414→	}
415→	ref := strings.TrimSpace(string(out))
416→	if strings.HasPrefix(ref, "refs/heads/") {
417→		return strings.TrimPrefix(ref, "refs/heads/")
418→	}
419→	return detachedHEADDisplay
420→}
