220→func runTrailCreate(cmd *cobra.Command, title, body, base, branch, statusStr string, checkout bool) error {
221→	w := cmd.OutOrStdout()
222→	errW := cmd.ErrOrStderr()
223→
224→	repo, err := strategy.OpenRepository(context.Background())
225→	if err != nil {
226→		return fmt.Errorf("failed to open repository: %w", err)
227→	}
228→
229→	// Determine base branch
230→	if base == "" {
231→		base = strategy.GetDefaultBranchName(repo)
232→		if base == "" {
233→			base = defaultBaseBranch
234→		}
235→	}
236→
237→	_, currentBranch, _ := IsOnDefaultBranch(context.Background()) //nolint:errcheck // best-effort detection
238→	interactive := !cmd.Flags().Changed("title") && !cmd.Flags().Changed("branch")
239→
240→	if interactive {
241→		// Interactive flow: title → body → branch (derived) → status
242→		if err := runTrailCreateInteractive(&title, &body, &branch, &statusStr); err != nil {
243→			return err
244→		}
245→	} else {
246→		// Non-interactive: derive missing values from provided flags
247→		if branch == "" {
248→			if cmd.Flags().Changed("title") {
249→				branch = slugifyTitle(title)
250→			} else {
251→				branch = currentBranch
252→			}
253→		}
254→		if title == "" {
255→			title = trail.HumanizeBranchName(branch)
256→		}
257→	}
258→	if branch == "" {
259→		return errors.New("branch name is required")
260→	}
261→
262→	// Create the branch if it doesn't exist
263→	needsCreation := branchNeedsCreation(repo, branch)
264→	if needsCreation {
265→		if err := createBranch(repo, branch); err != nil {
266→			return fmt.Errorf("failed to create branch %q: %w", branch, err)
267→		}
268→		fmt.Fprintf(w, "Created branch %s\n", branch)
269→	} else if currentBranch != branch {
270→		fmt.Fprintf(errW, "Note: trail will be created for branch %q (not the current branch)\n", branch)
271→	}
272→
273→	// Check if trail already exists for this branch
274→	store := trail.NewStore(repo)
275→	existing, err := store.FindByBranch(branch)
276→	if err == nil && existing != nil {
277→		fmt.Fprintf(w, "Trail already exists for branch %q (ID: %s)\n", branch, existing.TrailID)
278→		return nil
279→	}
280→
281→	// Determine status
282→	var trailStatus trail.Status
283→	if statusStr != "" {
284→		trailStatus = trail.Status(statusStr)
285→		if !trailStatus.IsValid() {
286→			return fmt.Errorf("invalid status %q: valid values are %s", statusStr, formatValidStatuses())
287→		}
288→	} else {
289→		trailStatus = trail.StatusDraft
290→	}
291→
292→	// Generate trail ID
293→	trailID, err := trail.GenerateID()
294→	if err != nil {
295→		return fmt.Errorf("failed to generate trail ID: %w", err)
296→	}
297→
298→	// Get author (GitHub username, falls back to git user.name)
299→	authorName := getTrailAuthor(repo)
300→
301→	now := time.Now()
302→	metadata := &trail.Metadata{
303→		TrailID:   trailID,
304→		Branch:    branch,
305→		Base:      base,
306→		Title:     title,
307→		Body:      body,
308→		Status:    trailStatus,
309→		Author:    authorName,
310→		Assignees: []string{},
311→		Labels:    []string{},
312→		CreatedAt: now,
313→		UpdatedAt: now,
314→	}
315→
316→	if err := store.Write(metadata, nil, nil); err != nil {
317→		return fmt.Errorf("failed to create trail: %w", err)
318→	}
319→
320→	fmt.Fprintf(w, "Created trail %q for branch %s (ID: %s)\n", title, branch, trailID)
321→
322→	// Push the branch and trail data to origin
323→	if needsCreation {
324→		if err := pushBranchToOrigin(branch); err != nil {
325→			fmt.Fprintf(errW, "Warning: failed to push branch: %v\n", err)
326→		} else {
327→			fmt.Fprintf(w, "Pushed branch %s to origin\n", branch)
328→		}
329→	}
330→	if err := strategy.PushTrailsBranch(context.Background(), "origin"); err != nil {
331→		fmt.Fprintf(errW, "Warning: failed to push trail data: %v\n", err)
332→	}
333→
334→	// Checkout the branch if requested or prompted
335→	if needsCreation && currentBranch != branch {
336→		shouldCheckout := checkout
337→		if !shouldCheckout && !cmd.Flags().Changed("checkout") {
338→			// Interactive: ask whether to checkout
339→			form := NewAccessibleForm(
340→				huh.NewGroup(
341→					huh.NewConfirm().
342→						Title(fmt.Sprintf("Check out branch %s?", branch)).
343→						Value(&shouldCheckout),
344→				),
345→			)
346→			if formErr := form.Run(); formErr == nil && shouldCheckout {
347→				checkout = true
348→			}
349→		}
350→		if checkout {
351→			if err := CheckoutBranch(context.Background(), branch); err != nil {
352→				return fmt.Errorf("failed to checkout branch %q: %w", branch, err)
353→			}
354→			fmt.Fprintf(w, "Switched to branch %s\n", branch)
355→		}
356→	}
357→
358→	return nil
359→}
