import (
	"bufio"
	"os"
)

// collectPerfEntries reads the log file and returns the last N perf entries,
// newest first. If hookFilter is non-empty, only entries matching that op are returned.
func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
	f, err := os.Open(logFile)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	// Read all perf entries (log files are bounded in practice)
	var all []perfEntry
	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := scanner.Text()
		entry := parsePerfEntry(line)
		if entry == nil {
			continue
		}
		if hookFilter != "" && entry.Op != hookFilter {
			continue
		}
		all = append(all, *entry)
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}

	// Take last N, newest first
	if len(all) > last {
		all = all[len(all)-last:]
	}
	// Reverse to newest first
	for i, j := 0, len(all)-1; i < j; i, j = i+1, j-1 {
		all[i], all[j] = all[j], all[i]
	}

	return all, nil
}
```

