// perf_cmd.go
package cli

import (
	"fmt"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

func newPerfCmd() *cobra.Command {
	var last int
	var hookFilter string

	cmd := &cobra.Command{
		Use:   "perf",
		Short: "Show hook performance traces",
		Long: `Parse performance traces from the log file and display step-level
timing breakdowns for recent hook invocations.

Perf traces are logged at DEBUG level. To enable them, set:
  ENTIRE_LOG_LEVEL=DEBUG
or add "log_level": "DEBUG" to .entire/settings.json.

Examples:
  entire perf                          Show last hook invocation
  entire perf --last 5                 Show last 5 invocations
  entire perf --hook post-commit       Show only post-commit traces`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			ctx := cmd.Context()
			repoRoot, err := paths.WorktreeRoot(ctx)
			if err != nil {
				return fmt.Errorf("not a git repository: %w", err)
			}

			logFile := filepath.Join(repoRoot, logging.LogsDir, "entire.log")
			entries, err := collectPerfEntries(logFile, last, hookFilter)
			if err != nil {
				return fmt.Errorf("failed to read log file: %w", err)
			}

			renderPerfEntries(cmd.OutOrStdout(), entries)
			return nil
		},
	}

	cmd.Flags().IntVar(&last, "last", 1, "Show last N hook invocations")
	cmd.Flags().StringVar(&hookFilter, "hook", "", "Filter by hook type (e.g. post-commit, prepare-commit-msg, pre-push)")

	return cmd
}
```

