120→// collectPerfEntries reads a JSONL log file and returns the last N perf entries,
121→// ordered newest first. If hookFilter is non-empty, only entries with a matching
122→// Op field are included.
123→func collectPerfEntries(logFile string, last int, hookFilter string) ([]perfEntry, error) {
124→	f, err := os.Open(logFile) //nolint:gosec // logFile is a CLI-resolved path, not user-supplied input
125→	if err != nil {
126→		return nil, fmt.Errorf("opening perf log: %w", err)
127→	}
128→	defer f.Close()
129→
130→	var entries []perfEntry
131→
132→	scanner := bufio.NewScanner(f)
133→	for scanner.Scan() {
134→		entry := parsePerfEntry(scanner.Text())
135→		if entry == nil {
136→			continue
137→		}
138→		if hookFilter != "" && entry.Op != hookFilter {
139→			continue
140→		}
141→		entries = append(entries, *entry)
142→	}
143→
144→	if err := scanner.Err(); err != nil {
145→		return nil, fmt.Errorf("reading perf log: %w", err)
146→	}
147→
148→	// Take the last N entries
149→	if len(entries) > last {
150→		entries = entries[len(entries)-last:]
151→	}
152→
153→	// Reverse so newest entries are first
154→	for i, j := 0, len(entries)-1; i < j; i, j = i+1, j-1 {
155→		entries[i], entries[j] = entries[j], entries[i]
156→	}
157→
158→	return entries, nil
159→}
160→

159→	return entries, nil
160→}
