func TestEnd_DuplicateChildNames_Disambiguated(t *testing.T) {
	t.Parallel()
	ctx := context.Background()

	ctx, parent := Start(ctx, "post-commit")

	// Simulate a loop creating children with the same names (e.g., per-session spans)
	_, c1 := Start(ctx, "check_content")
	c1.duration = 3000 * time.Millisecond
	c1.ended = true

	_, c2 := Start(ctx, "save_state")
	c2.duration = 5 * time.Millisecond
	c2.ended = true

	// Second iteration — same names
	_, c3 := Start(ctx, "check_content")
	c3.duration = 0
	c3.ended = true

	_, c4 := Start(ctx, "save_state")
	c4.duration = 2 * time.Millisecond
	c4.ended = true

	parent.End()

	// Verify children are all present
	if len(parent.children) != 4 {
		t.Fatalf("expected 4 children, got %d", len(parent.children))
	}

	// Build the same key map that End() produces to verify uniqueness
	keys := make(map[string]int64)
	seen := make(map[string]int)
	for _, child := range parent.children {
		n := seen[child.name]
		seen[child.name] = n + 1
		key := child.name
		if n > 0 {
			key = fmt.Sprintf("%s.%d", child.name, n)
		}
		keys[key] = child.duration.Milliseconds()
	}

	// First occurrences keep original name
	if v, ok := keys["check_content"]; !ok || v != 3000 {
		t.Errorf("check_content = %d, want 3000 (got ok=%v)", v, ok)
	}
	if v, ok := keys["save_state"]; !ok || v != 5 {
		t.Errorf("save_state = %d, want 5 (got ok=%v)", v, ok)
	}

	// Duplicates get .1 suffix
	if v, ok := keys["check_content.1"]; !ok || v != 0 {
		t.Errorf("check_content.1 = %d, want 0 (got ok=%v)", v, ok)
	}
	if v, ok := keys["save_state.1"]; !ok || v != 2 {
		t.Errorf("save_state.1 = %d, want 2 (got ok=%v)", v, ok)
	}
}

